19:import com.cockpitbench.climatix.telemetry.schema.TelemetrySchemaRegistry
20:import java.time.Clock
21:
22:class TelemetryPipeline(
23:    private val schemas: TelemetrySchemaRegistry,
24:    private val consent: ConsentPolicy,
25:    private val redactor: TelemetryRedactor,
26:    private val sampling: SamplingPolicy,
27:    private val buffer: TelemetryRingBuffer,
28:    private val batcher: TelemetryBatcher,
29:    private val sink: TelemetrySink,
30:    private val stateMachine: UploadStateMachine,
31:    private val health: TelemetryHealth,
32:    private val clock: Clock,
33:) {
34:    fun record(event: TelemetryEvent, consentState: ConsentState): Boolean {
35:        schemas.validate(event)
36:        if (!consent.permits(event, consentState) || !sampling.include(event)) return false
37:        buffer.offer(redactor.redact(event))
38:        return true
39:    }
40:
41:    fun flush(): Result<UploadReceipt?> {
42:        val envelope = batcher.next(buffer) ?: return Result.success(null)
43:        stateMachine.start(envelope)
44:        return sink.upload(envelope).fold(
45:            onSuccess = { receipt ->
46:                stateMachine.succeeded(receipt)
47:                health.success(envelope.sequence)
48:                Result.success(receipt)
49:            },
50:            onFailure = { failure ->
51:                health.failure()
52:                stateMachine.failed(clock.instant())
53:                Result.failure(failure)
54:            },
55:        )
56:    }
57:
58:    fun health() = health.snapshot(clock.instant(), buffer, stateMachine.state)
59:}
