17:package com.cockpitbench.climatix.telemetry
18:
19:import java.time.Duration
20:import java.time.Instant
21:
22:sealed interface UploadState {
23:    data object Idle : UploadState
24:    data class Uploading(val sequence: Long, val attempt: Int) : UploadState
25:    data class BackingOff(val sequence: Long, val until: Instant, val attempt: Int) : UploadState
26:    data class Suspended(val reason: String) : UploadState
27:}
28:
29:class UploadStateMachine(private val backoff: RetryBackoff) {
30:    var state: UploadState = UploadState.Idle
31:        private set
32:
33:    fun start(envelope: TelemetryEnvelope): UploadState.Uploading {
34:        check(state is UploadState.Idle)
35:        return UploadState.Uploading(envelope.sequence, 0).also { state = it }
36:    }
37:
38:    fun succeeded(receipt: UploadReceipt) {
39:        val active = state as? UploadState.Uploading ?: error("No upload in progress")
40:        require(active.sequence == receipt.envelopeSequence)
41:        state = UploadState.Idle
42:    }
43:
44:    fun failed(now: Instant, serverRetryAfterSeconds: Long? = null): UploadState.BackingOff {
45:        val active = state as? UploadState.Uploading ?: error("No upload in progress")
46:        val delay: Duration = backoff.delayFor(active.attempt, serverRetryAfterSeconds)
47:        return UploadState.BackingOff(active.sequence, now.plus(delay), active.attempt + 1).also { state = it }
48:    }
49:
50:    fun resume(now: Instant): Boolean {
51:        val backingOff = state as? UploadState.BackingOff ?: return false
52:        if (now < backingOff.until) return false
53:        state = UploadState.Uploading(backingOff.sequence, backingOff.attempt)
54:        return true
55:    }
56:
57:    fun suspend(reason: String) { state = UploadState.Suspended(reason) }
58:    fun reset() { state = UploadState.Idle }
59:}
