17:package com.cockpitbench.climatix.telemetry
18:
19:import java.security.MessageDigest
20:
21:class TelemetryRedactor(private val salt: ByteArray) {
22:    private val deniedKeys = setOf("vin", "account", "email", "phone", "location", "latitude", "longitude")
23:    private val pseudonymousKeys = setOf("vehicleProfile", "driverProfile", "device")
24:
25:    fun redact(event: TelemetryEvent): TelemetryEvent {
26:        val attributes = event.attributes.mapNotNull { (key, value) ->
27:            when {
28:                key in deniedKeys -> null
29:                key in pseudonymousKeys -> key to pseudonym(value)
30:                value.length > 256 -> key to value.take(256)
31:                else -> key to value
32:            }
33:        }.toMap()
34:        return event.copy(attributes = attributes)
35:    }
36:
37:    private fun pseudonym(value: String): String {
38:        val digest = MessageDigest.getInstance("SHA-256")
39:        digest.update(salt)
40:        return digest.digest(value.toByteArray()).take(12).joinToString("") { "%02x".format(it) }
41:    }
42:}
