17:package com.cockpitbench.climatix.telemetry
18:
19:import java.util.ArrayDeque
20:
21:class TelemetryRingBuffer(private val capacity: Int) {
22:    private val events = ArrayDeque<TelemetryEvent>()
23:    private var dropped = 0L
24:
25:    init { require(capacity > 0) }
26:
27:    @Synchronized fun offer(event: TelemetryEvent) {
28:        if (events.size == capacity) {
29:            val removable = events.indexOfFirst { it.priority < TelemetryPriority.SAFETY }
30:            if (removable < 0) {
31:                dropped += 1
32:                return
33:            }
34:            val retained = events.toMutableList().also { it.removeAt(removable) }
35:            events.clear()
36:            events.addAll(retained)
37:            dropped += 1
38:        }
39:        events.addLast(event)
40:    }
41:
42:    @Synchronized fun drain(maximum: Int): List<TelemetryEvent> = buildList {
43:        repeat(minOf(maximum.coerceAtLeast(0), events.size)) { add(events.removeFirst()) }
44:    }
45:
46:    @Synchronized fun size(): Int = events.size
47:    @Synchronized fun droppedCount(): Long = dropped
48:}
